<?php
declare(strict_types=1);
require dirname(__DIR__).'/src/community.php';
$path=parse_url($_SERVER['REQUEST_URI'],PHP_URL_PATH)?:'/';
$path=preg_replace('~^/public(?=/|$)~','',$path)?:'/';
$page='catalog';$m=null;$type='';
if(preg_match('~^/movie/([1-9][0-9]*)/?$~D',$path,$a)){$page='movie';try{$m=movie((int)$a[1]);}catch(Throwable $ex){error_log($ex->getMessage());$m=null;}}
elseif(preg_match('~^/read/([1-9][0-9]*)/([a-z]+)/?$~D',$path,$a)){$page='read';try{$m=movie((int)$a[1]);}catch(Throwable $ex){error_log($ex->getMessage());$m=null;}$type=$a[2];if(!isset(TYPES[$type]) || ($m && !contentOf($m,$type)))$m=null;}
elseif($path!=='/'){$page='notfound';}
if(($page==='movie'||$page==='read')&&!$m){http_response_code(404);$page='notfound';}
$error='';$items=[];$genres=[];$count=0;$pages=1;$p=1;
$q=trim((string)($_GET['q']??''));$y=trim((string)($_GET['year']??''));$g=trim((string)($_GET['genre']??''));$k=trim((string)($_GET['kind']??''));
$q=mb_substr($q,0,100);$g=mb_substr($g,0,60);$y=preg_match('/^\d{4}$/D',$y)?$y:'';$k=isset(TYPES[$k])?$k:'';
if($page==='catalog'){
 try{$p=max(1,min(100000,(int)($_GET['page']??1)));[$items,$count,$p,$pages]=catalog($q,$y,$g,$k,$p);$genres=allGenres();}catch(Throwable $ex){$error='Не удалось открыть каталог. Проверьте наличие SQLite-базы и таблицы movies.';error_log($ex->getMessage());http_response_code(503);}
}
$docTitle=$page==='movie'?title($m):($page==='read'?TYPES[$type][0].' — '.title($m):'Фанфик — истории по мотивам кино');
function navQuery(int $page):string{return '/?'.http_build_query(array_filter(['q'=>$GLOBALS['q'],'year'=>$GLOBALS['y'],'genre'=>$GLOBALS['g'],'kind'=>$GLOBALS['k'],'page'=>$page],fn($v)=>$v!==''));}
?><!doctype html>
<html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#14131c"><meta name="description" content="Полные сюжеты фильмов, развязки и фанфики по мотивам кино."><title><?=e($docTitle)?></title><link rel="stylesheet" href="/assets/site.css"></head>
<body><header class="topbar"><div class="wrap head"><a class="logo" href="/"><span class="logo-mark">✦</span> Фанфик<span class="logo-sub">истории кино</span></a><nav><a href="/">Каталог</a><a href="/?kind=novel">Романы</a><a href="/?kind=fantasy">Фанфики</a><a href="/admin.php">Админка</a></nav></div></header>
<main class="wrap">
<?php if($page==='catalog'): ?>
<section class="hero"><div class="eyebrow">КИНО · ИСТОРИИ · ВООБРАЖЕНИЕ</div><h1>У каждого фильма<br><em>есть продолжение.</em></h1><p>Читайте полные сюжеты, узнавайте концовки и открывайте альтернативные истории любимых фильмов.</p><form class="search" method="get" action="/"><input name="q" aria-label="Поиск фильма" placeholder="Название фильма…" value="<?=e($q)?>"><button type="submit">Найти <span aria-hidden="true">→</span></button></form></section>
<form class="filters" method="get" action="/"><input type="hidden" name="q" value="<?=e($q)?>"><label>Год <input type="number" min="1880" max="2100" name="year" placeholder="Любой" value="<?=e($y)?>"></label><label>Жанр <select name="genre"><option value="">Все жанры</option><?php foreach($genres as $genre):?><option value="<?=e($genre)?>" <?=$g===$genre?'selected':''?>><?=e($genre)?></option><?php endforeach;?></select></label><label>Читать <select name="kind"><option value="">Все истории</option><?php foreach(TYPES as $key=>$entry):?><option value="<?=e($key)?>" <?=$k===$key?'selected':''?>><?=e($entry[0])?></option><?php endforeach;?></select></label><button class="filter-btn">Применить</button><a class="reset" href="/">Сбросить</a></form>
<div class="section-head"><h2>Библиотека фильмов</h2><span><?=number_format($count,0,',',' ')?> историй</span></div>
<?php if($error):?><div class="notice"><?=e($error)?></div><?php elseif(!$items):?><div class="empty"><h3>Ничего не найдено</h3><p>Попробуйте изменить поисковый запрос или фильтры.</p></div><?php else:?><div class="movie-grid"><?php foreach($items as $item):?><a class="movie-card" href="<?=linkMovie((int)$item['id'])?>"><div class="poster"><?php if($poster=urlPoster((string)$item['poster_url'])):?><img src="/poster.php?id=<?=(int)$item['id']?>" alt="" loading="lazy" referrerpolicy="no-referrer" onerror="this.style.display='none'"><?php endif;?><span class="poster-fallback">✦</span></div><div class="card-body"><span class="card-meta"><?=e($item['year']?:'Кино')?> · <?=e(excerpt((string)$item['genres'],44)?:'Фильм')?></span><h3 title="<?=e(title($item))?>"><?=e(catalogTitle($item))?></h3><span class="card-link">Открыть историю ↗</span></div></a><?php endforeach;?></div>
<?php if($pages>1):?><nav class="pagination"><?php if($p>1):?><a href="<?=e(navQuery($p-1))?>">← Назад</a><?php endif;?><span>Страница <?=$p?> из <?=$pages?></span><?php if($p<$pages):?><a href="<?=e(navQuery($p+1))?>">Вперёд →</a><?php endif;?></nav><?php endif; endif;?>
<?php commentsWidget('site'); ?>
<?php elseif($page==='movie'):?>
<a class="back" href="/">← Все фильмы</a><section class="detail"><div class="detail-poster"><?php if($poster=urlPoster((string)$m['poster_url'])):?><img src="/poster.php?id=<?=(int)$m['id']?>" alt="" referrerpolicy="no-referrer"><?php else:?><span>✦</span><?php endif;?></div><div><div class="eyebrow">ИСТОРИИ ПО МОТИВАМ КИНО</div><h1><?=e(title($m))?></h1><?php if(trim((string)$m['title_ru'])!=='' && $m['title_ru']!==$m['title']):?><p class="original"><?=e($m['title'])?></p><?php endif;?><p class="chips"><span><?=e($m['year']?:'Год не указан')?></span><?php foreach(array_slice(preg_split('/[,;|]/u',(string)$m['genres'])?:[],0,4) as $genre):if(trim($genre)!==''):?><span><?=e(trim($genre))?></span><?php endif;endforeach;?></p><p class="detail-lead">Выберите историю, которую хотите прочитать. Полный сюжет, финал и авторские вариации в разных жанрах — всё в одной библиотеке.</p><div class="story-grid"><?php foreach(TYPES as $key=>$entry):$text=contentOf($m,$key);if(!$text)continue;?><a class="story" href="/read/<?=(int)$m['id']?>/<?=e($key)?>"><span class="story-symbol"><?=match($key){'plot'=>'▤','ending'=>'◈','novel'=>'❖',default=>'✧'}?></span><span><strong><?=e($entry[0])?></strong><small><?=e(excerpt($text,95))?></small></span><span>↗</span></a><?php endforeach;?></div><?php if(!array_filter(array_keys(TYPES),fn($t)=>contentOf($m,$t)!=='')):?><p class="notice">Для этого фильма пока нет доступных текстов.</p><?php endif;?></div></section><?php commentsWidget('movie',(int)$m['id']); ?>
<?php elseif($page==='read'):?>
<div class="reader-head"><a class="back" href="<?=linkMovie((int)$m['id'])?>">← К фильму</a><div class="reader-tools"><button id="font-down" aria-label="Уменьшить шрифт">А−</button><button id="font-up" aria-label="Увеличить шрифт">А+</button><button id="width-toggle" aria-label="Изменить ширину текста">↔</button><button id="theme-toggle" aria-label="Переключить тему">☾</button></div></div><article class="reader" id="reader"><div class="eyebrow"><?=e(TYPES[$type][0])?></div><h1><?=e(title($m))?></h1><div class="reader-meta"><?=e($m['year']?:'')?> · <?=e(TYPES[$type][0])?></div><div class="prose"><?=renderText(contentOf($m,$type))?></div><div class="reader-end">✦<p>Конец истории</p><a href="<?=linkMovie((int)$m['id'])?>">Другие версии истории →</a></div></article><?php commentsWidget('story',(int)$m['id'],$type); ?><div class="reading-progress" id="reading-progress"></div>
<?php else:?><section class="empty"><h1>Страница не найдена</h1><p>Возможно, история была перемещена.</p><a href="/">Вернуться в каталог</a></section><?php endif;?>
</main><footer class="footer"><div class="wrap">Фанфик <span>·</span> Кино — это начало истории.</div></footer><script src="/assets/site.js" defer></script></body></html>
